/* Bench preparation snapshots, conserved sample bottles and titre-based acid/base analysis. */
const benchTitChem={HCl:{name:'Hydrochloric acid',side:'acid'},NaOH:{name:'Sodium hydroxide',side:'base'},Na2CO3:{name:'Sodium carbonate',side:'base',primary:true},NaHCO3:{name:'Sodium bicarbonate',side:'base'},CH3COOH:{name:'Ethanoic acid',side:'acid'},H2SO4:{name:'Sulfuric acid',side:'acid'},KHC8H4O4:{name:'Potassium hydrogen phthalate',side:'acid',primary:true}};
let benchTitState=benchTitLoad(),benchTitChoice={mode:'assay',flask:'',burette:''};
function benchTitLoad(){try{const x=JSON.parse(localStorage.getItem('simlab-bench-titration-v1')||'null');if(x?.version===1&&Array.isArray(x.samples))return x;}catch{}return {version:1,samples:[],reports:[],manualBackup:null};}
function benchTitSave(){try{localStorage.setItem('simlab-bench-titration-v1',JSON.stringify(benchTitState));}catch{}if(typeof persistWorkspace==='function')persistWorkspace();}
function benchTitId(){return 'bt'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);}
function benchTitBottle(id){return benchTitState.samples.find(x=>x.id===id);}
function benchTitCanon(f){return f==='KC8H5O4'?'KHC8H4O4':f;}
function benchTitSolution(a){
 if(a?.contents?.some(c=>c.type==='publicationCustom'))return {valid:false,message:'Publication/custom identities need a validated titration model. Use a supported bench reagent for quantitative acid/base import.'};if(!a||!(Number(a.volume)>0))return {valid:false,message:'Add a solution before transferring a bottle to titration.'};
 if(a.contents.some(c=>Number(c.mass)>0&&!c.solidDissolved))return {valid:false,message:'Dissolve the weighed solid before exporting a solution.'};
 if(a.contents.length>1&&!a.mixed)return {valid:false,message:'Mix the vessel before exporting a representative solution.'};
 const e=benchEntries(a.contents),active=new Map();for(const c of e){const f=benchTitCanon(c.f);if(c.type==='water')continue;if(['NaCl','KCl'].includes(f))continue;if(!benchTitChem[f])return {valid:false,message:'This mixture is not a supported single acid/base preparation. Use a separate aliquot for other analyses.'};if(!Number.isFinite(c.n)||c.n<0)return {valid:false,message:'A reagent amount or concentration is missing.'};if(c.n>0)active.set(f,(active.get(f)||0)+c.n);}
 if(active.size!==1)return {valid:false,message:'Titration import needs one supported acid or base. Competing acids, bases and reaction mixtures are not assigned a unique concentration.'};
 const [formula,n]=[...active][0],C=n/(Number(a.volume)/1000);if(!Number.isFinite(C)||C<=0||C>1)return {valid:false,message:'The bench titration model supports positive concentrations up to 1 mol/L.'};
 const directStock=a.contents.length===1&&!a.contents[0].solidStock&&Number(a.contents[0].volume)>0,verified=!!(a.preparedAtMark||a.solutionVolumeVerified||directStock);
 return {valid:true,formula,chemical:benchTitChem[formula],concentration:C,moles:n,volume:Number(a.volume),verified};
}
function benchSampleExportControls(a){if(!transferToolIsVessel(a))return '';const p=benchTitSolution(a),name=a.benchReagentName||`${benchVesselLabel(a)} · ${p.valid?p.chemical.name:'prepared reagent'}`,role=a.benchExportRole||(p.valid&&p.chemical.primary?'known':'unknown');return `<details class="tool-preparation bench-export"><summary>Prepare / send reagent to titration</summary><label for="benchReagentName">Reagent bottle name<input id="benchReagentName" maxlength="80" value="${esc(name)}"></label><label for="benchReagentRole">Use in titration<select id="benchReagentRole"><option value="unknown" ${role==='unknown'?'selected':''}>Unknown concentration · hide in titration</option><option value="known" ${role==='known'?'selected':''}>Known concentration · reference solution</option></select></label>${p.valid?`<p>${esc(p.chemical.name)} · calculated ${ttFmt(p.concentration)} mol/L · ${p.verified?'defined stock / final-volume preparation':'approximate displayed-volume basis'}</p>`:`<p>${esc(p.message)}</p>`}<label for="benchExportVolume">Solution to transfer (mL)<input id="benchExportVolume" type="number" min="0.000001" max="${Number(a.volume)||0}" step="any" value="${Math.min(60,Number(a.volume)||0)}"></label><button type="button" class="btn small" data-bench-tit="export" ${p.valid?'':'disabled'}>Transfer bottle to titration library</button><button type="button" class="btn secondary small" data-bench-tit="open">Open titration bench</button><p id="benchExportStatus" role="status">${esc(a.benchExportMessage||'Each exported bottle keeps its own composition and remaining volume. The source vessel loses the transferred amount.')}</p><small>For a known solution from solid, dissolve below the final volume and make up in a volumetric flask, then transfer aliquots to separate beakers. Unknowns hide concentration in the titration interface. Arbitrary mixtures remain outside this acid/base import model.</small></details>`;}
function benchTitExport(a,name,role,volume){const p=benchTitSolution(a);if(!p.valid)return {error:p.message};if(!Number.isFinite(volume)||volume<=0||volume>p.volume)return {error:'Enter a finite transfer volume no larger than the source contents.'};if(!['known','unknown'].includes(role))return {error:'Choose known reference or unknown sample.'};if(role==='known'&&!p.verified)return {error:'A known reference needs a defined stock or final-volume preparation. Make up in a volumetric flask, then transfer the solution into your beakers.'};const fraction=volume/p.volume,sample={id:benchTitId(),name:String(name||p.chemical.name).trim().slice(0,80),formula:p.formula,chemical:p.chemical.name,role,truthC:p.concentration,assignedC:role==='known'?p.concentration:null,remaining:volume,initialVolume:volume,verified:p.verified,sourceVessel:a.id,sourceLabel:benchVesselLabel(a),sourceContents:JSON.parse(JSON.stringify(a.contents)),createdAt:Date.now(),basis:p.verified?'defined stock / final solution volume':'displayed-volume approximation'};
 a.contents=a.contents.map(c=>({...c,volume:Number(((Number(c.volume)||0)*(1-fraction)).toPrecision(14)),mass:Number(((Number(c.mass)||0)*(1-fraction)).toPrecision(14))})).filter(c=>c.volume>1e-12||c.mass>1e-12);a.volume=Number((p.volume-volume).toPrecision(14));a.benchReagentName=sample.name;a.benchExportRole=role;a.benchExportMessage=`Transferred ${ttFmt(volume)} mL to “${sample.name}”. ${ttFmt(a.volume)} mL remains in this vessel.`;benchTitState.samples.push(sample);benchTitSave();return {sample};}
function benchTitPair(flask,burette){const key=flask+'|'+burette,pairs={
 'HCl|NaOH':[1,1,'HCl + NaOH → NaCl + H₂O','Phenolphthalein'],
 'NaOH|HCl':[1,1,'NaOH + HCl → NaCl + H₂O','Methyl orange'],
 'H2SO4|NaOH':[1,2,'H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O','Phenolphthalein'],
 'NaOH|H2SO4':[2,1,'2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O','Methyl orange'],
 'CH3COOH|NaOH':[1,1,'CH₃COOH + NaOH → CH₃COONa + H₂O','Phenolphthalein'],
 'Na2CO3|HCl':[1,2,'Na₂CO₃ + 2HCl → 2NaCl + CO₂ + H₂O','Methyl orange'],
 'NaHCO3|HCl':[1,1,'NaHCO₃ + HCl → NaCl + CO₂ + H₂O','Methyl orange'],
 'KHC8H4O4|NaOH':[1,1,'KHC₈H₄O₄ + NaOH → KNaC₈H₄O₄ + H₂O','Phenolphthalein']};const p=pairs[key];return p?{a:p[0],b:p[1],equation:p[2],indicator:p[3]}:null;}
function benchTitLibraryHtml(){const samples=benchTitState.samples,mode=benchTitChoice.mode,flasks=samples.filter(s=>s.role===(mode==='standardize'?'known':'unknown')),burettes=samples.filter(s=>s.role===(mode==='standardize'?'unknown':'known')),options=(list,selected)=>'<option value="">Choose a bottle</option>'+list.map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${esc(s.name)} · ${ttFmt(s.remaining)} mL</option>`).join('');return `<section class="panel bench-tit-library"><div class="bench-tit-heading"><div><div class="eyebrow">FROM YOUR OPEN BENCH</div><h2>Prepared reagent bottles</h2></div><button class="btn secondary small" type="button" data-bench-tit="bench">Return to Open Bench</button></div><p>Keep different reagents in separate beakers. Export a measured bottle from the vessel’s “Prepare / send reagent to titration” controls.</p>${samples.length?`<div class="ch-scroll"><table class="table"><thead><tr><th>Bottle</th><th>Role</th><th>Concentration</th><th>Remaining</th></tr></thead><tbody>${samples.map(s=>`<tr><td>${esc(s.name)}<small>${esc(s.chemical)}</small></td><td>${s.role==='known'?'Known reference':'Unknown'}</td><td>${s.role==='known'?ttFmt(s.assignedC)+' mol/L':'Hidden · determine by titration'}</td><td>${ttFmt(s.remaining)} mL</td></tr>`).join('')}</tbody></table></div>`:'<p class="notice">No bench bottles yet. Prepare and mix a solution on the Open Bench, then export it from its vessel.</p>'}<div class="bench-tit-grid"><label>Analysis<select id="benchTitMode"><option value="assay" ${mode==='assay'?'selected':''}>Analyse an unknown sample in the flask</option><option value="standardize" ${mode==='standardize'?'selected':''}>Standardise an unknown titrant in the burette</option></select></label><label>Flask solution<select id="benchTitFlask">${options(flasks,benchTitChoice.flask)}</select></label><label>Burette solution<select id="benchTitBurette">${options(burettes,benchTitChoice.burette)}</select></label></div><button type="button" class="btn" data-bench-tit="start">Load selected bottles into titration</button><p id="benchTitLibraryStatus" role="status"></p><details><summary>Add a supplied known reference bottle</summary><div class="bench-tit-grid"><label>Reference<select id="benchRefChemical"><option value="HCl">Hydrochloric acid</option><option value="NaOH">Sodium hydroxide</option></select></label><label>Known concentration (mol/L)<input id="benchRefC" type="number" min="0.000001" max="1" step="any" value="0.1"></label><label>Bottle volume (mL)<input id="benchRefV" type="number" min="0.000001" step="any" value="100"></label></div><button type="button" class="btn soft small" data-bench-tit="reference">Add supplied reference</button><small>This is a declared known reference in the simulation, separate from your bench preparations.</small></details>${titration.benchSession?'<button type="button" class="btn secondary small" data-bench-tit="manual">Return to manual preparation mode</button>':''}<small>Supported documented acid/base pairs only. Amounts, dilution, aliquot volume and reaction coefficients determine the simulation; recorded titres determine the reported concentration. <a href="bench-titration-reference.txt" target="_blank" rel="noopener">Methods &amp; model limits</a></small></section>`;}
function benchTitStart(mode,flaskId,buretteId){if(!['assay','standardize'].includes(mode))return 'Choose a supported analysis mode.';const a=benchTitBottle(flaskId),b=benchTitBottle(buretteId),p=a&&b&&benchTitPair(a.formula,b.formula);if(!a||!b||a.id===b.id)return 'Choose two different reagent bottles.';if(!p)return 'This acid/base pair is not supported. Use KHP with NaOH, carbonate/bicarbonate with HCl, or a listed acid with NaOH.';if(mode==='standardize'&&(a.role!=='known'||b.role!=='unknown')||mode==='assay'&&(a.role!=='unknown'||b.role!=='known'))return 'For analysis use an unknown flask sample and known titrant; for standardisation use a known flask reference and unknown titrant.';if(!(a.remaining>0)||!(b.remaining>0))return 'One bottle is empty. Transfer more prepared solution from the bench.';if(titration.benchSession&&titration.runs?.length)benchTitArchive();if(!titration.benchSession)benchTitState.manualBackup=JSON.parse(JSON.stringify(titration));titration={...freshTitration('acid'),sampleVol:Math.min(10,a.remaining),deliveryStep:.5,benchSession:{id:benchTitId(),mode,flask:JSON.parse(JSON.stringify(a)),burette:JSON.parse(JSON.stringify(b)),pair:p,reserved:false,reservedAliquot:0,reveal:false},indicatorName:p.indicator};if(typeof studyState!=='undefined')studyState.titrationChallenge=false;benchTitCapture(false);benchTitSave();return '';}
function benchTitPreparation(){const s=titration.benchSession;if(!s)return null;return {valid:Number.isFinite(s.flask.truthC)&&s.flask.truthC>0,concentration:s.flask.truthC,moles:s.flask.truthC*s.flask.initialVolume/1000,summary:s.flask.role==='unknown'?`Bench bottle “${s.flask.name}”; concentration hidden for analysis.`:`Bench reference “${s.flask.name}”: ${ttFmt(s.flask.assignedC)} mol/L.`,message:'The bench preparation snapshot is invalid.'};}
function benchTitCapture(readDOM=true){const s=titration.benchSession;if(!s)return;const value=id=>readDOM?document.getElementById(id)?.value:undefined;for(const [field,id]of [['sampleVol','sampleVol'],['deliveryStep','step']])if(value(id)!==undefined)titration[field]=Number(value(id));for(const key of ['initialReading','finalReading'])if(value(key)!==undefined)titration[key]=value(key);titration.unknownSpecies=s.flask.chemical;titration.knownChemical=s.burette.chemical;titration.analyteCoeff=s.pair.a;titration.titrantCoeff=s.pair.b;titration.stoich=s.pair.a/s.pair.b;titration.reactionEquation=s.pair.equation;titration.titrantC=s.burette.truthC;titration.expectedSource='bench';titration.mode='simulated';titration.analyteConc='';titration.expected=ttPositive(titration.sampleVol)?s.flask.truthC*Number(titration.sampleVol)*s.pair.b/(s.burette.truthC*s.pair.a):null;return {d:titrations.acid,defaultPair:false};}
function benchTitSetupHtml(){const s=titration.benchSession,a=benchTitBottle(s.flask.id),b=benchTitBottle(s.burette.id);return `<div class="workspace"><div class="panel workpanel bench-tit-run"><div class="eyebrow">BENCH-LINKED EXPERIMENT</div><h2>${s.mode==='standardize'?'Standardise the burette reagent':'Analyse the flask sample'}</h2><p><b>Flask:</b> ${esc(s.flask.name)} · ${s.flask.role==='known'?ttFmt(s.flask.assignedC)+' mol/L reference':'unknown concentration'}<br><b>Burette:</b> ${esc(s.burette.name)} · ${s.burette.role==='known'?ttFmt(s.burette.assignedC)+' mol/L reference':'unknown concentration'}</p><div class="bench-tit-grid"><label>Aliquot in flask (mL)<input id="sampleVol" type="number" min="0.000001" step="any" value="${titration.sampleVol}" ${s.reserved?'disabled':''}></label><label>Indicator<select id="indicatorSelect">${['Phenolphthalein','Methyl orange','Bromothymol blue'].map(n=>`<option ${titration.indicatorName===n?'selected':''}>${n}</option>`).join('')}</select></label></div><p class="notice">${esc(s.pair.equation)}<br>Flask : burette coefficients = ${s.pair.a} : ${s.pair.b}. Suggested indicator: ${esc(s.pair.indicator)}.</p><p>Remaining in flask-supply bottle: <b>${ttFmt(a?.remaining||0)} mL</b>. Remaining titrant: <b>${ttFmt(b?.remaining||0)} mL</b>.</p><p id="titrationStatus" class="titration-status" role="status">Deliver titrant gradually, observe the indicator and record your own endpoint. The unknown concentration and predicted titre are hidden.</p><small>The first addition reserves one aliquot from the flask-supply bottle. Every delivered volume is deducted from the titrant bottle. Restarting discards used liquid; it does not return it to either bottle.</small></div></div>`;}
function benchTitrationDecorate(html){const library=benchTitLibraryHtml();if(!titration.benchSession)return library+html;const begin=html.indexOf('<div class="workspace">'),end=html.indexOf('<div class="panel workpanel volume-record-panel">',begin);if(begin<0||end<0)throw Error('Bench titration setup slot is missing.');html=html.slice(0,begin)+benchTitSetupHtml()+html.slice(end);html=html.replace(/id="idealEndpoint"[^>]*/,'id="idealEndpoint" disabled title="Use your observed endpoint for this bench unknown"').replace(/id="completeTitration"[^>]*/,`id="completeTitration" ${titration.done||!titration.runs.length?'disabled':''}`);html=html.replace(/<p class="footer-note">[\s\S]*?<\/p>\s*$/,'<p class="footer-note">Bench-linked acid/base titration. Reported concentrations use recorded titres and the declared reference concentration. Unknown truth is used only to simulate the experiment. Weak-acid and carbonate colour changes are illustrative; gas loss, activities and full speciation are not modeled.</p>');return library+html;}
function benchTitDeliver(targetVolume){const s=titration.benchSession;if(!s||titration.done)return 'Start an unfinished bench-linked experiment.';benchTitCapture();const va=Number(titration.sampleVol),current=Number(titration.volume)||0,delta=targetVolume-current,a=benchTitBottle(s.flask.id),b=benchTitBottle(s.burette.id);if(!Number.isFinite(targetVolume)||targetVolume<=0||delta< -1e-12)return 'Enter a positive cumulative delivered volume. Delivered liquid cannot be returned to the bottle.';if(!ttPositive(va))return 'Enter a finite, positive aliquot volume.';if(s.reserved&&Math.abs(va-s.reservedAliquot)>1e-10)return 'Restart the current run before changing its aliquot volume.';if(!a||!b)return 'A selected bottle is no longer available.';if(!s.reserved&&va>a.remaining+1e-10)return 'Not enough sample remains for this aliquot.';if(delta>b.remaining+1e-10)return 'Not enough titrant remains. Export another bottle from the bench.';
 if(!s.reserved){a.remaining=Math.max(0,Number((a.remaining-va).toPrecision(14)));s.reserved=true;s.reservedAliquot=va;}b.remaining=Math.max(0,Number((b.remaining-Math.max(0,delta)).toPrecision(14)));titration.volume=Number(targetVolume.toPrecision(15));titration.history.push(titration.volume);titration._mixingPending=true;benchTitSave();return '';}
function benchTitSnapshot(){const s=titration.benchSession,ref=s.mode==='standardize'?s.flask:s.burette;return {bench:true,sessionId:s.id,analysisMode:s.mode,sampleVol:Number(titration.sampleVol),titre:Number(titration.volume),referenceC:Number(ref.assignedC),analyteCoeff:s.pair.a,titrantCoeff:s.pair.b,reactionEquation:s.pair.equation,unknownSpecies:s.mode==='standardize'?s.burette.chemical:s.flask.chemical,flaskName:s.flask.name,buretteName:s.burette.name,flaskId:s.flask.id,buretteId:s.burette.id,trueConcentration:s.mode==='standardize'?s.burette.truthC:s.flask.truthC,titrantC:s.burette.truthC};}
function benchTitRun(r){if(![r.sampleVol,r.titre,r.referenceC,r.analyteCoeff,r.titrantCoeff].every(ttPositive))return null;const standardize=r.analysisMode==='standardize',referenceMoles=r.referenceC*(standardize?r.sampleVol:r.titre)/1000,unknownMoles=referenceMoles*(standardize?r.titrantCoeff/r.analyteCoeff:r.analyteCoeff/r.titrantCoeff),unknownVolume=(standardize?r.titre:r.sampleVol)/1000;return {...r,referenceMoles,unknownMoles,unknownVolume,concentration:unknownMoles/unknownVolume};}
function benchTitrationResult(){const rows=(titration.runs||[]).map(benchTitRun);if(!rows.length||rows.some(x=>!x))return null;const moles=rows.reduce((sum,r)=>sum+r.unknownMoles,0),aliquot=rows.reduce((sum,r)=>sum+r.unknownVolume,0);return {rows,moles,aliquot,concentration:moles/aliquot,same:rows.every(r=>r.sampleVol===rows[0].sampleVol&&r.referenceC===rows[0].referenceC),meanTitre:rows.reduce((sum,r)=>sum+r.titre,0)/rows.length};}
function benchTitTable(){const r=benchTitrationResult();if(!r)return '<p class="notice">Record a titre to calculate concentration from your own endpoint.</p>';return `<div class="ch-scroll"><table class="table"><thead><tr><th>Run</th><th>Titre / mL</th><th>Aliquot / mL</th><th>Reference / mol L⁻¹</th><th>Calculated / mol L⁻¹</th></tr></thead><tbody>${r.rows.map((x,i)=>`<tr><td>${i+1}</td><td>${ttFmt(x.titre)}</td><td>${ttFmt(x.sampleVol)}</td><td>${ttFmt(x.referenceC)}</td><td>${ttFmt(x.concentration)}</td></tr>`).join('')}</tbody></table></div>`;}
function benchTitCalculation(){const result=benchTitrationResult();if(!result)return '<div class="notice">Record a valid endpoint titre. No concentration is substituted for an unrecorded measurement.</div>';const r=result.rows.at(-1),s=titration.benchSession,std=s.mode==='standardize';return `<div class="resultbox calculation-breakdown"><div class="eyebrow">${std?'BURETTE REAGENT STANDARDISATION':'FLASK SAMPLE ANALYSIS'}</div><div class="big">${ttFmt(result.concentration)} mol/L</div><b>${esc(r.unknownSpecies)} · calculated from recorded titres</b><div class="formula">${std?'Cᵦ = Cₐ × (Vₐ / Vₜ) × (b / a)':'Cₐ = Cᵦ × (Vₜ / Vₐ) × (a / b)'}</div><p>Latest run: reference moles = ${ttFmt(r.referenceC)} × (${ttFmt(std?r.sampleVol:r.titre)} / 1000) = ${ttFmt(r.referenceMoles)} mol.<br>Unknown moles = ${ttFmt(r.referenceMoles)} × ${std?r.titrantCoeff:r.analyteCoeff} / ${std?r.analyteCoeff:r.titrantCoeff} = ${ttFmt(r.unknownMoles)} mol.<br>Concentration = ${ttFmt(r.unknownMoles)} / ${ttFmt(r.unknownVolume)} L = ${ttFmt(r.concentration)} mol/L.</p>${result.rows.length>1?`<p>Combined result = Σ unknown moles / Σ corresponding unknown-solution volume = ${ttFmt(result.moles)} / ${ttFmt(result.aliquot)} = ${ttFmt(result.concentration)} mol/L. Each run keeps its own aliquot and reference concentration.</p>`:''}${titration.done?`<button class="btn secondary small" type="button" data-bench-tit="reveal">Compare with preparation value</button>${s.reveal?`<p>Simulation preparation value: ${ttFmt(r.trueConcentration)} mol/L. Relative difference: ${ttFmt(Math.abs(result.concentration/r.trueConcentration-1)<1e-10?0:100*(result.concentration/r.trueConcentration-1))}%.</p>`:''}${std?`<button class="btn small" type="button" data-bench-tit="certify" ${result.rows.length<2?'disabled':''}>Use calculated value as a working standard</button><small>Record at least two runs first. All recorded runs contribute; repeat rough or overshot titrations before assigning a working standard. The assigned value is your calculated result, not the hidden preparation value.</small>`:''}`:'<p>Complete the analysis to compare with the preparation value.</p>'}</div>`;}
function benchTitLog(){return titration.history.length?`<div class="list">${titration.history.slice(-5).reverse().map(v=>`<div class="listitem"><b>${ttFmt(v)} mL</b><span>Recorded delivery · observe indicator</span></div>`).join('')}</div>`:'<div class="empty">No titrant delivered yet. Observe the indicator and reduce the addition near its transition.</div>';}
function benchTitRestart(all=false){if(all)benchTitArchive();Object.assign(titration,{volume:0,history:[],initialReading:'',finalReading:'',runSampleKey:null,done:false});if(all){titration.runs=[];titration.titreReadings=[];}Object.assign(titration.benchSession,{reserved:false,reservedAliquot:0,reveal:false});benchTitSave();}
function benchTitArchive(){const r=benchTitrationResult();if(r)benchTitState.reports.push({id:benchTitId(),createdAt:Date.now(),mode:titration.benchSession.mode,rows:JSON.parse(JSON.stringify(r.rows)),concentration:r.concentration});}
function benchTitStatus(message){const el=document.getElementById('titrationStatus');if(el)el.textContent=message||'Use your recorded endpoint to determine the unknown concentration. No predicted titre is displayed.';}
function benchTitBind(){if(page!=='titration'||!titration.benchSession)return;benchTitCapture();const refresh=()=>render(),error=msg=>{if(msg)benchTitStatus(msg);else refresh();};document.getElementById('addTitrant').onclick=()=>{const step=Number(document.getElementById('step').value);if(!ttPositive(step)||step<1e-9){benchTitStatus('Enter a finite positive delivery step.');return;}titration.deliveryStep=step;error(benchTitDeliver(Number(titration.volume)+step));};document.getElementById('useBuretteReadings').onclick=()=>{const a=document.getElementById('initialReading').value,b=document.getElementById('finalReading').value;if(a===''||b===''||!Number.isFinite(Number(a))||!Number.isFinite(Number(b))||Number(a)<0||Number(b)<=Number(a)){benchTitStatus('Enter finite readings with final greater than initial.');return;}error(benchTitDeliver(Number(b)-Number(a)));};document.getElementById('markEndpoint').onclick=()=>{if(titration.done||!titration.benchSession.reserved||!ttPositive(titration.volume))return;const r=benchTitSnapshot();titration.runs.push(r);titration.titreReadings=titration.runs.map(x=>x.titre);benchTitRestart(false);refresh();};document.getElementById('restartCurrentRun').onclick=()=>{benchTitRestart(false);refresh();};document.getElementById('resetTitration').onclick=()=>{benchTitRestart(true);refresh();};document.getElementById('completeTitration').onclick=()=>{if(!benchTitrationResult())return;titration.done=true;benchTitSave();refresh();};document.getElementById('indicatorSelect').onchange=e=>{titration.indicatorName=e.target.value;refresh();};document.getElementById('sampleVol').onchange=e=>{if(!titration.benchSession.reserved)titration.sampleVol=Number(e.target.value);benchTitCapture();benchTitStatus();};document.getElementById('idealEndpoint').disabled=true;}
function benchTitLibraryStatus(text){const e=document.getElementById('benchTitLibraryStatus');if(e)e.textContent=text;}
document.addEventListener('change',e=>{if(e.target.id==='benchTitMode'){benchTitChoice={mode:e.target.value,flask:'',burette:''};render();}if(e.target.id==='benchTitFlask')benchTitChoice.flask=e.target.value;if(e.target.id==='benchTitBurette')benchTitChoice.burette=e.target.value;});
document.addEventListener('click',e=>{const action=e.target.closest?.('[data-bench-tit]')?.dataset.benchTit;if(!action)return;
 if(action==='open'){go('titration');return;}if(action==='bench'){go('bench');return;}
 if(action==='export'){const a=selectedEquipment(),name=document.getElementById('benchReagentName')?.value,role=document.getElementById('benchReagentRole')?.value,v=Number(document.getElementById('benchExportVolume')?.value),out=benchTitExport(a,name,role,v);if(out.error){document.getElementById('benchExportStatus').textContent=out.error;return;}redrawBench();document.getElementById('gasStatus').textContent=a.benchExportMessage;return;}
 if(action==='reference'){const f=document.getElementById('benchRefChemical').value,C=Number(document.getElementById('benchRefC').value),v=Number(document.getElementById('benchRefV').value);if(!['HCl','NaOH'].includes(f)||!Number.isFinite(C)||C<=0||C>1||!ttPositive(v)){benchTitLibraryStatus('Enter a positive reference concentration up to 1 M and a positive bottle volume.');return;}benchTitState.samples.push({id:benchTitId(),name:`Supplied ${benchTitChem[f].name} reference`,formula:f,chemical:benchTitChem[f].name,role:'known',truthC:C,assignedC:C,remaining:v,initialVolume:v,verified:true,basis:'declared supplied reference',createdAt:Date.now()});benchTitSave();render();return;}
 if(action==='start'){const msg=benchTitStart(document.getElementById('benchTitMode').value,document.getElementById('benchTitFlask').value,document.getElementById('benchTitBurette').value);if(msg)benchTitLibraryStatus(msg);else render();return;}
 if(action==='manual'){if(titration.benchSession)benchTitArchive();titration=benchTitState.manualBackup?JSON.parse(JSON.stringify(benchTitState.manualBackup)):freshTitration('acid');benchTitSave();render();return;}
 if(action==='reveal'){if(titration.done){titration.benchSession.reveal=true;render();}return;}
 if(action==='certify'){const r=benchTitrationResult(),s=titration.benchSession,b=s&&benchTitBottle(s.burette.id);if(!titration.done||s?.mode!=='standardize'||!r||r.rows.length<2||!b)return;b.assignedC=r.concentration;b.role='known';b.standardisation={rows:JSON.parse(JSON.stringify(r.rows)),assignedC:r.concentration,createdAt:Date.now()};benchTitSave();render();benchTitLibraryStatus(`Assigned ${ttFmt(b.assignedC)} mol/L from your recorded titres to “${b.name}”.`);}
});
function benchTitPreparationPrediction(items){const e=benchEntries(items);if(!e.some(x=>benchTitCanon(x.f)==='KHC8H4O4')||e.some(x=>x.type!=='water'&&benchTitCanon(x.f)!=='KHC8H4O4'))return null;return {product:'Potassium hydrogen phthalate reference preparation',equation:'KHC₈H₄O₄(s) → K⁺(aq) + HC₈H₄O₄⁻(aq)',note:e.some(x=>x.solidStock&&!x.solidDissolved)?'Weighed KHP is present. Add water and use Mix to dissolve measured solid.':'KHP is a monoprotic acid reference for 1:1 titration with NaOH. Other mixtures are not assigned products by this preparation rule.',color:'#f7faf8',solutionColor:'#f7faf8',precipitate:false,gas:null,status:'qualitative',foodTest:true};}
